    getPropertyValueManager(property: Property): PropertyValueManager<unknown> {
        switch (property.key) {
            case sysmlBase.INSTANCE.IOccurrenceDefinition_isIndividual.key: return this._isIndividual;
            case sysmlBase.INSTANCE.IDefinition_isVariation.key: return this._isVariation;
            case sysmlBase.INSTANCE.IType_isAbstract.key: return this._isAbstract;
            case sysmlBase.INSTANCE.IType_isSufficient.key: return this._isSufficient;
            case sysmlBase.INSTANCE.IType_isConjugated.key: return this._isConjugated;
            case sysmlBase.INSTANCE.IElement_elementId.key: return this._elementId;
            case sysmlBase.INSTANCE.IElement_aliasIds.key: return this._aliasIds;
            case sysmlBase.INSTANCE.IElement_declaredShortName.key: return this._declaredShortName;
            case sysmlBase.INSTANCE.IElement_declaredName.key: return this._declaredName;
            case sysmlBase.INSTANCE.IElement_shortName.key: return this._shortName;
            case sysmlBase.INSTANCE.IElement_name.key: return this._name;
            case sysmlBase.INSTANCE.IElement_qualifiedName.key: return this._qualifiedName;
            case sysmlBase.INSTANCE.IElement_isImpliedIncluded.key: return this._isImpliedIncluded;
            case sysmlBase.INSTANCE.IElement_isLibraryElement.key: return this._isLibraryElement;
            default: return super.getPropertyValueManager(property);
        }
    }

