        super(classifier, id, receiveDelta, parentInfo);
        this._ownedSubclassification = new RequiredMultiContainmentValueManager<Subclassification>(sysmlBase.INSTANCE.IClassifier_ownedSubclassification, this);
        this._ownedSpecialization = new RequiredMultiContainmentValueManager<Specialization>(sysmlBase.INSTANCE.IType_ownedSpecialization, this);
        this._ownedFeatureMembership = new RequiredMultiContainmentValueManager<FeatureMembership>(sysmlBase.INSTANCE.IType_ownedFeatureMembership, this);
        this._feature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_feature, this);
