        super(classifier, id, receiveDelta, parentInfo);
        this._relatedFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IConnector_relatedFeature, this);
        this._association = new RequiredMultiContainmentValueManager<Association>(sysmlBase.INSTANCE.IConnector_association, this);
        this._connectorEnd = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IConnector_connectorEnd, this);
        this._sourceFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IConnector_sourceFeature, this);
        this._targetFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IConnector_targetFeature, this);
        this._defaultFeaturingType = new RequiredMultiContainmentValueManager<Type>(sysmlBase.INSTANCE.IConnector_defaultFeaturingType, this);
        this._owningFeatureMembership = new RequiredMultiContainmentValueManager<FeatureMembership>(sysmlBase.INSTANCE.IFeature_owningFeatureMembership, this);
        this._owningType = new RequiredMultiContainmentValueManager<Type>(sysmlBase.INSTANCE.IFeature_owningType, this);
