        super(classifier, id, receiveDelta, parentInfo);
        this._expression = new RequiredMultiContainmentValueManager<Expression>(sysmlBase.INSTANCE.IFunction_expression, this);
        this._result = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IFunction_result, this);
        this._isModelLevelEvaluable = new RequiredPropertyValueManager<boolean>(sysmlBase.INSTANCE.IFunction_isModelLevelEvaluable, this);
