        this._ownedFeatureMembership = new RequiredMultiContainmentValueManager<FeatureMembership>(sysmlBase.INSTANCE.IType_ownedFeatureMembership, this);
        this._feature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_feature, this);
        this._ownedFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_ownedFeature, this);
        this._input = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_input, this);
        this._output = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_output, this);
        this._isAbstract = new RequiredPropertyValueManager<boolean>(sysmlBase.INSTANCE.IType_isAbstract, this);
        this._inheritedMembership = new RequiredMultiContainmentValueManager<Membership>(sysmlBase.INSTANCE.IType_inheritedMembership, this);
        this._endFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_endFeature, this);
        this._ownedEndFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_ownedEndFeature, this);
        this._isSufficient = new RequiredPropertyValueManager<boolean>(sysmlBase.INSTANCE.IType_isSufficient, this);
        this._ownedConjugator = new RequiredMultiContainmentValueManager<Conjugation>(sysmlBase.INSTANCE.IType_ownedConjugator, this);
        this._isConjugated = new RequiredPropertyValueManager<boolean>(sysmlBase.INSTANCE.IType_isConjugated, this);
        this._inheritedFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IType_inheritedFeature, this);
        this._multiplicity = new RequiredMultiContainmentValueManager<Multiplicity>(sysmlBase.INSTANCE.IType_multiplicity, this);
        this._unioningType = new RequiredMultiContainmentValueManager<Type>(sysmlBase.INSTANCE.IType_unioningType, this);
