        super(classifier, id, receiveDelta, parentInfo);
        this._itemDefinition = new RequiredMultiContainmentValueManager<Structure>(sysmlBase.INSTANCE.IItemUsage_itemDefinition, this);
        this._occurrenceDefinition = new RequiredMultiContainmentValueManager<Class>(sysmlBase.INSTANCE.IOccurrenceUsage_occurrenceDefinition, this);
