        super(classifier, id, receiveDelta, parentInfo);
        this._referencedFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IReferenceSubsetting_referencedFeature, this);
        this._referencingFeature = new RequiredMultiContainmentValueManager<Feature>(sysmlBase.INSTANCE.IReferenceSubsetting_referencingFeature, this);
