        this._general = new RequiredMultiContainmentValueManager<Type>(sysmlBase.INSTANCE.ISpecialization_general, this);
        this._specific = new RequiredMultiContainmentValueManager<Type>(sysmlBase.INSTANCE.ISpecialization_specific, this);
        this._owningType = new RequiredMultiContainmentValueManager<Type>(sysmlBase.INSTANCE.ISpecialization_owningType, this);
        this._relatedElement = new RequiredMultiContainmentValueManager<Element>(sysmlBase.INSTANCE.IRelationship_relatedElement, this);
        this._target = new RequiredMultiContainmentValueManager<Element>(sysmlBase.INSTANCE.IRelationship_target, this);
        this._source = new RequiredMultiContainmentValueManager<Element>(sysmlBase.INSTANCE.IRelationship_source, this);
        this._owningRelatedElement = new RequiredMultiContainmentValueManager<Element>(sysmlBase.INSTANCE.IRelationship_owningRelatedElement, this);
        this._ownedRelatedElement = new RequiredMultiContainmentValueManager<Element>(sysmlBase.INSTANCE.IRelationship_ownedRelatedElement, this);
        this._isImplied = new RequiredPropertyValueManager<boolean>(sysmlBase.INSTANCE.IRelationship_isImplied, this);
        this._owningMembership = new RequiredMultiContainmentValueManager<OwningMembership>(sysmlBase.INSTANCE.IElement_owningMembership, this);
        this._ownedRelationship = new RequiredMultiContainmentValueManager<Relationship>(sysmlBase.INSTANCE.IElement_ownedRelationship, this);
        this._owningRelationship = new RequiredMultiContainmentValueManager<Relationship>(sysmlBase.INSTANCE.IElement_owningRelationship, this);
        this._owningNamespace = new RequiredMultiContainmentValueManager<Namespace>(sysmlBase.INSTANCE.IElement_owningNamespace, this);
        this._elementId = new RequiredPropertyValueManager<string>(sysmlBase.INSTANCE.IElement_elementId, this);
        this._owner = new RequiredMultiContainmentValueManager<Element>(sysmlBase.INSTANCE.IElement_owner, this);
        this._ownedElement = new RequiredMultiContainmentValueManager<Element>(sysmlBase.INSTANCE.IElement_ownedElement, this);
