    getPropertyValueManager(property: Property): PropertyValueManager<unknown> {
        switch (property.key) {
            case sysmlBase.INSTANCE.IOccurrenceUsage_isIndividual.key: return this._isIndividual;
            case sysmlBase.INSTANCE.IOccurrenceUsage_portionKind.key: return this._portionKind;
            case sysmlBase.INSTANCE.IUsage_mayTimeVary.key: return this._mayTimeVary;
            case sysmlBase.INSTANCE.IUsage_isReference.key: return this._isReference;
            case sysmlBase.INSTANCE.IUsage_isVariation.key: return this._isVariation;
            case sysmlBase.INSTANCE.IFeature_isUnique.key: return this._isUnique;
            case sysmlBase.INSTANCE.IFeature_isOrdered.key: return this._isOrdered;
            case sysmlBase.INSTANCE.IFeature_isComposite.key: return this._isComposite;
            case sysmlBase.INSTANCE.IFeature_isEnd.key: return this._isEnd;
            case sysmlBase.INSTANCE.IFeature_isDerived.key: return this._isDerived;
            case sysmlBase.INSTANCE.IFeature_isPortion.key: return this._isPortion;
            case sysmlBase.INSTANCE.IFeature_isVariable.key: return this._isVariable;
            case sysmlBase.INSTANCE.IFeature_isConstant.key: return this._isConstant;
            case sysmlBase.INSTANCE.IFeature_direction.key: return this._direction;
            case sysmlBase.INSTANCE.IFeature_isNonunique.key: return this._isNonunique;
            case sysmlBase.INSTANCE.IType_isAbstract.key: return this._isAbstract;
            case sysmlBase.INSTANCE.IType_isSufficient.key: return this._isSufficient;
            case sysmlBase.INSTANCE.IType_isConjugated.key: return this._isConjugated;
            case sysmlBase.INSTANCE.IElement_elementId.key: return this._elementId;
            case sysmlBase.INSTANCE.IElement_aliasIds.key: return this._aliasIds;
            case sysmlBase.INSTANCE.IElement_declaredShortName.key: return this._declaredShortName;
            case sysmlBase.INSTANCE.IElement_declaredName.key: return this._declaredName;
            case sysmlBase.INSTANCE.IElement_shortName.key: return this._shortName;
            case sysmlBase.INSTANCE.IElement_name.key: return this._name;
            case sysmlBase.INSTANCE.IElement_qualifiedName.key: return this._qualifiedName;
            case sysmlBase.INSTANCE.IElement_isImpliedIncluded.key: return this._isImpliedIncluded;
            case sysmlBase.INSTANCE.IElement_isLibraryElement.key: return this._isLibraryElement;
            default: return super.getPropertyValueManager(property);
        }
    }

