        super(classifier, id, receiveDelta, parentInfo);
        this._mayTimeVary = new RequiredPropertyValueManager<boolean>(sysmlBase.INSTANCE.IUsage_mayTimeVary, this);
        this._isReference = new RequiredPropertyValueManager<boolean>(sysmlBase.INSTANCE.IUsage_isReference, this);
