        this._variantMembership = new RequiredMultiContainmentValueManager<VariantMembership>(sysmlBase.INSTANCE.IUsage_variantMembership, this);
        this._owningDefinition = new RequiredMultiContainmentValueManager<Definition>(sysmlBase.INSTANCE.IUsage_owningDefinition, this);
        this._owningUsage = new RequiredMultiContainmentValueManager<Usage>(sysmlBase.INSTANCE.IUsage_owningUsage, this);
        this._nestedUsage = new RequiredMultiContainmentValueManager<Usage>(sysmlBase.INSTANCE.IUsage_nestedUsage, this);
        this._definition = new RequiredMultiContainmentValueManager<sysmlClassifier>(sysmlBase.INSTANCE.IUsage_definition, this);
        this._usage = new RequiredMultiContainmentValueManager<Usage>(sysmlBase.INSTANCE.IUsage_usage, this);
        this._directedUsage = new RequiredMultiContainmentValueManager<Usage>(sysmlBase.INSTANCE.IUsage_directedUsage, this);
        this._nestedReference = new RequiredMultiContainmentValueManager<ReferenceUsage>(sysmlBase.INSTANCE.IUsage_nestedReference, this);
        this._nestedAttribute = new RequiredMultiContainmentValueManager<AttributeUsage>(sysmlBase.INSTANCE.IUsage_nestedAttribute, this);
        this._nestedEnumeration = new RequiredMultiContainmentValueManager<EnumerationUsage>(sysmlBase.INSTANCE.IUsage_nestedEnumeration, this);
        this._nestedOccurrence = new RequiredMultiContainmentValueManager<OccurrenceUsage>(sysmlBase.INSTANCE.IUsage_nestedOccurrence, this);
        this._nestedItem = new RequiredMultiContainmentValueManager<ItemUsage>(sysmlBase.INSTANCE.IUsage_nestedItem, this);
        this._nestedPart = new RequiredMultiContainmentValueManager<PartUsage>(sysmlBase.INSTANCE.IUsage_nestedPart, this);
        this._nestedPort = new RequiredMultiContainmentValueManager<PortUsage>(sysmlBase.INSTANCE.IUsage_nestedPort, this);
        this._nestedConnection = new RequiredMultiContainmentValueManager<ConnectorAsUsage>(sysmlBase.INSTANCE.IUsage_nestedConnection, this);
        this._nestedFlow = new RequiredMultiContainmentValueManager<FlowUsage>(sysmlBase.INSTANCE.IUsage_nestedFlow, this);
