    static create(id: LionWebId, receiveDelta?: DeltaReceiver, parentInfo?: Parentage): ViewpointUsage {
        return new ViewpointUsage(sysmlBase.INSTANCE.ViewpointUsage, id, receiveDelta, parentInfo);
    }

